<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * A simulated mixi-2006 user. Wraps a regular User row whose public
 * activity (diaries, topics, footprints) is generated by the tick engine.
 */
class Persona extends Model
{
    protected $fillable = [
        'user_id', 'archetype', 'gender', 'age', 'prefecture', 'dialect',
        'voice', 'interests', 'activity', 'seed', 'last_sim_active_at',
    ];

    /** @return array<string, string> */
    protected function casts(): array
    {
        return [
            'interests' => 'array',
            'age' => 'integer',
            'activity' => 'float',
            'seed' => 'integer',
            'last_sim_active_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }
}
